    intro:
      "உங்கள் மியூச்சுவல் ஃபண்ட் வாங்குதல்களையும் ரிடெம்ப்ஷன்களையும் உள்ளிட்டு, ஒவ்வொரு நிதியாண்டின் மூலதன ஆதாயத்தைப் பாருங்கள், முதலில் வாங்கியது முதலில் விற்கப்பட்டதாகப் பொருத்தி, வருமான வரிச் சட்டம் கையாளும் விதத்தில் பிரித்து, வரி கணக்கிடப்பட்டு.",
