    current: "தற்போதைய",
    daily: "தினசரி",
    "daily NAV": "தினசரி NAV",
    "date, benchmark_id, benchmark_name, currency and one of total_return_index or price. A total-return index is preferred: a growth-option NAV reinvests dividends, so a price index understates the benchmark and flatters the fund. Files are rejected whole, never partially imported.":
      "date, benchmark_id, benchmark_name, currency மற்றும் total_return_index அல்லது price இல் ஒன்று. டோட்டல்-ரிட்டர்ன் இண்டெக்ஸ் விரும்பப்படுகிறது: Growth ஆப்ஷன் NAV டிவிடெண்டுகளை மறுமுதலீடு செய்கிறது, எனவே விலை இண்டெக்ஸ் பெஞ்ச்மார்க்கைக் குறைத்துக் காட்டி ஃபண்டைச் சாதகமாகக் காட்டும். கோப்புகள் முழுமையாக நிராகரிக்கப்படுகின்றன, ஒருபோதும் பகுதியாக இறக்குமதி செய்யப்படுவதில்லை.",
