    sub_category: "sub_category",
    "terminal zero nav excluded": "இறுதிப் பூஜ்ஜிய NAV விலக்கப்பட்டது",
    "the {0}/{1}/{2}-year readings blended on horizon_weights, each horizon read through the first metric listed that has a value":
      "{0}/{1}/{2} ஆண்டு பதிவுகள் horizon_weights அடிப்படையில் கலக்கப்பட்டவை, ஒவ்வொரு காலமும் மதிப்பு உள்ள முதல் பட்டியலிட்ட அளவீட்டின் மூலம் படிக்கப்படுகிறது",
    "trailing {0} quarters": "கடந்த {0} காலாண்டுகள்",
    "volatility_{0}y": "volatility_{0}y",
    "{0} complete ({1}-month) calendar years": "{0} முழு ({1} மாத) நாள்காட்டி ஆண்டுகள்",
    "{0} distinct dated readings in scheme_aum_history (the horizon plus the one to grow from); below that, null with reason 'insufficient_aum_history'.":
      "scheme_aum_history யில் {0} தனித்த தேதியிட்ட பதிவுகள் (காலமும், வளர்ச்சி அளக்கத் தொடக்கமாக ஒன்றும்); அதற்குக் கீழ், 'insufficient_aum_history' காரணத்துடன் null.",
    "{0} eligible peers in the sub-category at that month end (MF_MIN_PEERS), the same floor every other peer-relative metric uses; below it the month end is excluded rather than ranked on a thin universe.":
      "அந்த மாத இறுதியில் துணை வகையில் {0} தகுதியான ஒத்த ஃபண்டுகள் (MF_MIN_PEERS), மற்ற ஒவ்வொரு ஒத்த-ஃபண்டு அளவீடும் பயன்படுத்தும் அதே குறைந்தபட்ச வரம்பு; அதற்குக் கீழ், மெல்லிய தொகுப்பில் ரேங்க் செய்யாமல் அந்த மாத இறுதி விலக்கப்படுகிறது.",
    "{0} eligible peers in the sub-category with a computed aum_family_latest (MF_MIN_PEERS), the same floor every other peer-relative metric uses; below it, null with reason 'insufficient_peer_universe'.":
      "கணக்கிடப்பட்ட aum_family_latest உடன் துணை வகையில் {0} தகுதியான ஒத்த ஃபண்டுகள் (MF_MIN_PEERS), மற்ற ஒவ்வொரு ஒத்த-ஃபண்டு அளவீடும் பயன்படுத்தும் அதே குறைந்தபட்ச வரம்பு; அதற்குக் கீழ், 'insufficient_peer_universe' காரணத்துடன் null.",
    "{0} eligible peers with a non-null value for that component's underlying metric (MF_MIN_PEERS), the same floor every other peer-relative metric in this document uses.":
      "அந்தக் கூறின் அடிப்படை அளவீட்டுக்கு null அல்லாத மதிப்பு கொண்ட {0} தகுதியான ஒத்த ஃபண்டுகள் (MF_MIN_PEERS), இந்த ஆவணத்தில் உள்ள மற்ற ஒவ்வொரு ஒத்த-ஃபண்டு அளவீடும் பயன்படுத்தும் அதே குறைந்தபட்ச வரம்பு.",
    "{0} matched monthly observations across every basket member, the same {1}-year floor the risk metrics use; below it the whole /basket response is null with reason 'insufficient_history'.":
      "பாஸ்கெட்டின் ஒவ்வொரு உறுப்பினரிடமும் {0} பொருந்திய மாதாந்திரப் பதிவுகள், ரிஸ்க் அளவீடுகள் பயன்படுத்தும் அதே {1} ஆண்டு குறைந்தபட்ச வரம்பு; அதற்குக் கீழ் முழு /basket பதிலும் 'insufficient_history' காரணத்துடன் null.",
    "{0} monthly contributions in the window": "விண்டோவில் {0} மாதாந்திர முதலீடுகள்",
    "{0} months": "{0} மாதங்கள்",
    "{0} months shared with every member of the style-factor basis, and a fit explaining at least {1}% of the fund's month-to-month movement (R-squared); below either, null with reason 'insufficient_observations' or 'style_basis_does_not_describe_this_fund'.":
      "பாணி-காரணி அடிப்படையின் ஒவ்வொரு உறுப்பினருடனும் பொதுவான {0} மாதங்கள், மற்றும் ஃபண்டின் மாதாந்திர அசைவில் குறைந்தது {1}% ஐ விளக்கும் பொருத்தம் (R-squared); ஏதேனும் ஒன்றுக்குக் கீழ், 'insufficient_observations' அல்லது 'style_basis_does_not_describe_this_fund' காரணத்துடன் null.",
    "{0} of {1} schemes have no benchmark mapped, so their benchmark-relative metrics are null with reason 'benchmark_not_mapped'. Largest unmapped sub-categories: Income ({2}), Growth ({3}), Liquid Fund ({4}). Add a rule to benchmark_map.yaml and import the matching index to cover them.":
      "{1} திட்டங்களில் {0} க்கு பெஞ்ச்மார்க் இணைக்கப்படவில்லை, எனவே அவற்றின் பெஞ்ச்மார்க் சார்ந்த அளவீடுகள் 'benchmark_not_mapped' காரணத்துடன் null. இணைக்கப்படாத பெரிய துணை வகைகள்: Income ({2}), Growth ({3}), Liquid Fund ({4}). அவற்றை உள்ளடக்க benchmark_map.yaml இல் ஒரு விதியைச் சேர்த்து, பொருந்தும் இண்டெக்ஸை இறக்குமதி செய்யுங்கள்.",
    "{0} valid windows (MF_MIN_ROLLING_WINDOWS)":
      "{0} செல்லுபடியான விண்டோக்கள் (MF_MIN_ROLLING_WINDOWS)",
    "{0} valid windows (MF_MIN_ROLLING_WINDOWS), each itself requiring {1} contributions":
      "{0} செல்லுபடியான விண்டோக்கள் (MF_MIN_ROLLING_WINDOWS), ஒவ்வொன்றுக்கும் {1} முதலீடுகள் தேவை",
    "{0} years": "{0} ஆண்டுகள்",
